template MerkleVerifier(levels) {
    signal input leaf;
    signal input path[levels];
    signal input direction[levels];
    signal output out;

    component hasher[levels];
    signal current_node;

    current_node <== leaf;

    for (var i = 0; i < levels; i++) {
        hasher[i] = Poseidon(2);
        if (direction[i] == 0) {
            hasher[i].inputs[0] <== current_node;
            hasher[i].inputs[1] <== path[i];
        } else {
            hasher[i].inputs[0] <== path[i];
            hasher[i].inputs[1] <== current_node;
        }
        current_node <== hasher[i].out;
    }

    out <== current_node;
}

template InferenceCheckMerkle(N_CONTEXT, TREE_DEPTH) {
    signal input context_ids[N_CONTEXT];
    signal input selected_id;
    signal input threshold;
    signal input weights_root;
    signal input leaf_weights[N_CONTEXT];
    signal input merkle_paths[N_CONTEXT][TREE_DEPTH];
    signal input merkle_paths_directions[N_CONTEXT][TREE_DEPTH];
    signal output valid;
    signal output ctx_hash;

    component hasher = Poseidon(N_CONTEXT + 1);
    for (var i = 0; i < N_CONTEXT; i++) {
        hasher.inputs[i] <== context_ids[i];
    }
    hasher.inputs[N_CONTEXT] <== selected_id;
    ctx_hash <== hasher.out;

    signal activation;
    activation <== 0;

    component verifier[N_CONTEXT];
    for (var i = 0; i < N_CONTEXT; i++) {
        verifier[i] = MerkleVerifier(TREE_DEPTH);
        verifier[i].leaf <== leaf_weights[i];
        for (var j = 0; j < TREE_DEPTH; j++) {
            verifier[i].path[j] <== merkle_paths[i][j];
            verifier[i].direction[j] <== merkle_paths_directions[i][j];
        }
        verifier[i].out === weights_root;
        activation <== activation + leaf_weights[i];
    }

    component ge = GreaterEqThan(32);
    ge.in[0] <== activation;
    ge.in[1] <== threshold;

    valid <== ge.out;
}

