const std = @import("std");

pub const VerificationError = error{
    InvariantViolated,
    PreconditionFailed,
    PostconditionFailed,
    OutOfMemory,
    InvalidArgument,
};

pub const InvariantRegistry = struct {
    allocator: std.mem.Allocator,

    const Entry = struct {
        name: []const u8,
        check_fn: *const fn (*anyopaque) bool,
        ctx: *anyopaque,
    };

    checks: std.ArrayList(Entry),

    pub fn init(allocator: std.mem.Allocator) InvariantRegistry {
        return .{
            .allocator = allocator,
            .checks = std.ArrayList(Entry).init(allocator),
        };
    }

    pub fn deinit(self: *InvariantRegistry) void {
        for (self.checks.items) |e| self.allocator.free(e.name);
        self.checks.deinit();
    }

    pub fn register(self: *InvariantRegistry, name: []const u8, check_fn: *const fn (*anyopaque) bool, ctx: *anyopaque) !void {
        const owned = try self.allocator.dupe(u8, name);
        try self.checks.append(.{ .name = owned, .check_fn = check_fn, .ctx = ctx });
    }

    pub fn verifyAll(self: *InvariantRegistry) !void {
        for (self.checks.items) |e| {
            if (!e.check_fn(e.ctx)) return VerificationError.InvariantViolated;
        }
    }
};

pub fn assertPrecondition(condition: bool) !void {
    if (!condition) return VerificationError.PreconditionFailed;
}

pub fn assertPostcondition(condition: bool) !void {
    if (!condition) return VerificationError.PostconditionFailed;
}

pub fn verifyGraphIntegrity(node_count: usize, edge_count: usize) bool {
    if (node_count == 0 and edge_count > 0) return false;
    return true;
}

pub fn verifyGrammarBalance(rule_count: usize, symbol_count: usize) bool {
    if (symbol_count < rule_count) return false;
    return true;
}
