pub const IngestionError = error{
    FileOpenError,
    ReadError,
    InvalidUtf8,
    OutOfMemory,
};

pub const TokenStream = struct {
    allocator: std.mem.Allocator,
     std.ArrayList(u8),

    pub fn init(allocator: std.mem.Allocator) TokenStream {
        return .{
            .allocator = allocator,
            .data = std.ArrayList(u8).init(allocator),
        };
    }

    pub fn deinit(self: *TokenStream) void {
        self.data.deinit();
    }

    pub fn toOwnedSlice(self: *TokenStream) ![]u8 {
        return try self.data.toOwnedSlice();
    }
};

pub fn ingestFile(allocator: std.mem.Allocator, path: []const u8, require_utf8: bool) !TokenStream {
    var file = std.fs.cwd().openFile(path, .{}) catch return IngestionError.FileOpenError;
    defer file.close();

    var stream = TokenStream.init(allocator);

    var br = std.io.bufferedReader(file.reader());
    var r = br.reader();

    var buf: [64 * 1024]u8 = undefined;
    while (true) {
        const n = r.read(&buf) catch return IngestionError.ReadError;
        if (n == 0) break;
        try stream.data.appendSlice(buf[0..n]);
    }

    if (require_utf8) {
        if (!std.unicode.utf8ValidateSlice(stream.data.items)) return IngestionError.InvalidUtf8;
    }

    return stream;
}
