const std = @import("std");

const Kind = enum(u8) { Guard, Terminal, NonTerminal };

const Rule = struct {
    id: u32,
    guard: *Symbol,
    refcount: usize,
    deleted: bool,
};

const Symbol = struct {
    kind: Kind,
    prev: *Symbol,
    next: *Symbol,
    terminal: u64,
    rule: ?*Rule,
};

fn symKey(s: *const Symbol) u64 {
    return switch (s.kind) {
        .Terminal => s.terminal,
        .NonTerminal => 0x8000_0000_0000_0000 | @as(u64, s.rule.?.id),
        .Guard => 0xFFFF_FFFF_FFFF_FFFF,
    };
}

fn digramKey(a: *const Symbol, b: *const Symbol) u128 {
    return (@as(u128, symKey(a)) << 64) | @as(u128, symKey(b));
}

pub const Grammar = struct {
    allocator: std.mem.Allocator,
    digrams: std.AutoHashMap(u128, *Symbol),
    rules: std.ArrayList(*Rule),
    root: *Rule,
    next_rule_id: u32,

    pub fn init(allocator: std.mem.Allocator) !Grammar {
        var g = Grammar{
            .allocator = allocator,
            .digrams = std.AutoHashMap(u128, *Symbol).init(allocator),
            .rules = std.ArrayList(*Rule).init(allocator),
            .root = undefined,
            .next_rule_id = 0,
        };
        g.root = try g.createRule();
        return g;
    }

    pub fn deinit(self: *Grammar) void {
        self.digrams.deinit();
        for (self.rules.items) |r| {
            if (r.deleted) continue;
            self.freeRuleSymbols(r);
            self.allocator.destroy(r);
        }
        self.rules.deinit();
    }

    fn freeRuleSymbols(self: *Grammar, r: *Rule) void {
        var it = r.guard.next;
        while (it != r.guard) {
            const nxt = it.next;
            self.allocator.destroy(it);
            it = nxt;
        }
        self.allocator.destroy(r.guard);
        r.deleted = true;
    }

    fn createSymbolGuard(self: *Grammar, r: *Rule) !*Symbol {
        const g = try self.allocator.create(Symbol);
        g.* = .{ .kind = .Guard, .prev = g, .next = g, .terminal = 0, .rule = r };
        return g;
    }

    fn createRule(self: *Grammar) !*Rule {
        const r = try self.allocator.create(Rule);
        r.* = .{ .id = self.next_rule_id, .guard = undefined, .refcount = 0, .deleted = false };
        self.next_rule_id += 1;
        r.guard = try self.createSymbolGuard(r);
        try self.rules.append(r);
        return r;
    }

    fn createTerminal(self: *Grammar, v: u64) !*Symbol {
        const s = try self.allocator.create(Symbol);
        s.* = .{ .kind = .Terminal, .prev = undefined, .next = undefined, .terminal = v, .rule = null };
        return s;
    }

    fn createNonTerminal(self: *Grammar, r: *Rule) !*Symbol {
        const s = try self.allocator.create(Symbol);
        s.* = .{ .kind = .NonTerminal, .prev = undefined, .next = undefined, .terminal = 0, .rule = r };
        r.refcount += 1;
        return s;
    }

    fn link(a: *Symbol, b: *Symbol) void {
        a.next = b;
        b.prev = a;
    }

    fn insertAfter(pos: *Symbol, s: *Symbol) void {
        const nxt = pos.next;
        link(pos, s);
        link(s, nxt);
    }

    fn detach(self: *Grammar, s: *Symbol) void {
        _ = self;
        link(s.prev, s.next);
    }

    fn removeDigramAt(self: *Grammar, s: *Symbol) void {
        if (s.kind == .Guard) return;
        if (s.next.kind == .Guard) return;
        const key = digramKey(s, s.next);
        if (self.digrams.get(key)) |cur| {
            if (cur == s) _ = self.digrams.remove(key);
        }
    }

    fn putDigramAt(self: *Grammar, s: *Symbol) !void {
        if (s.kind == .Guard) return;
        if (s.next.kind == .Guard) return;
        const key = digramKey(s, s.next);
        try self.digrams.put(key, s);
    }

    fn checkDigram(self: *Grammar, s: *Symbol) !void {
        if (s.kind == .Guard) return;
        if (s.next.kind == .Guard) return;
        const key = digramKey(s, s.next);
        if (self.digrams.get(key)) |other| {
            if (other != s and other.next != s) {
                try self.processMatch(other, s);
                return;
            }
        } else {
            try self.digrams.put(key, s);
        }
    }

    fn ruleBodyIsDigram(s: *Symbol) ?*Rule {
        if (s.prev.kind != .Guard) return null;
        if (s.next.next.kind != .Guard) return null;
        return s.prev.rule;
    }

    fn processMatch(self: *Grammar, first: *Symbol, second: *Symbol) !void {
        if (ruleBodyIsDigram(first)) |existing_rule| {
            try self.substitute(second, existing_rule);
            return;
        }

        var r = try self.createRule();
        const a = try self.cloneSymbolIntoRule(first, r);
        const b = try self.cloneSymbolIntoRule(first.next, r);
        insertAfter(r.guard, a);
        insertAfter(a, b);

        self.removeDigramAt(first);
        self.removeDigramAt(second);

        try self.substitute(first, r);
        try self.substitute(second, r);

        try self.putDigramAt(r.guard.next);
    }

    fn cloneSymbolIntoRule(self: *Grammar, src: *Symbol, r: *Rule) !*Symbol {
        return switch (src.kind) {
            .Terminal => try self.createTerminal(src.terminal),
            .NonTerminal => blk: {
                const rr = src.rule.?;
                rr.refcount += 1;
                const s = try self.allocator.create(Symbol);
                s.* = .{ .kind = .NonTerminal, .prev = undefined, .next = undefined, .terminal = 0, .rule = rr };
                break :blk s;
            },
            .Guard => unreachable,
        };
    }

    fn substitute(self: *Grammar, start: *Symbol, r: *Rule) !void {
        const left = start.prev;
        const a = start;
        const b = start.next;
        const right = b.next;

        self.removeDigramAt(left);
        self.removeDigramAt(a);
        self.removeDigramAt(b);

        detach(self, a);
        detach(self, b);

        if (a.kind == .NonTerminal) self.decrementRef(a.rule.?);
        if (b.kind == .NonTerminal) self.decrementRef(b.rule.?);

        self.allocator.destroy(a);
        self.allocator.destroy(b);

        const nt = try self.createNonTerminal(r);
        insertAfter(left, nt);

        try self.checkDigram(left);
        try self.checkDigram(nt);

        _ = right;
    }

    fn decrementRef(self: *Grammar, r: *Rule) void {
        if (r.refcount == 0) return;
        r.refcount -= 1;
        if (r.refcount == 1) self.expandRule(r) catch {};
    }

    fn findSingleReference(self: *Grammar, target: *Rule) ?*Symbol {
        var cur = self.root.guard.next;
        while (cur != self.root.guard) : (cur = cur.next) {
            if (cur.kind == .NonTerminal and cur.rule.? == target) return cur;
        }
        for (self.rules.items) |rr| {
            if (rr.deleted or rr == self.root) continue;
            var it = rr.guard.next;
            while (it != rr.guard) : (it = it.next) {
                if (it.kind == .NonTerminal and it.rule.? == target) return it;
            }
        }
        return null;
    }

    fn expandRule(self: *Grammar, r: *Rule) !void {
        if (r.deleted) return;
        const ref = self.findSingleReference(r) orelse return;

        const left = ref.prev;
        const right = ref.next;

        self.removeDigramAt(left);
        self.removeDigramAt(ref);

        detach(self, ref);
        self.allocator.destroy(ref);

        r.refcount = 0;

        var body_it = r.guard.next;
        var insert_pos = left;
        while (body_it != r.guard) : (body_it = body_it.next) {
            const cloned = try self.cloneSymbolIntoRule(body_it, self.root);
            insertAfter(insert_pos, cloned);
            insert_pos = cloned;
        }

        link(insert_pos, right);

        var check = left;
        var steps: usize = 0;
        while (steps < 4) : (steps += 1) {
            try self.checkDigram(check);
            check = check.next;
            if (check.kind == .Guard) break;
        }

        self.freeRuleSymbols(r);
    }

    pub fn addByte(self: *Grammar, b: u8) !void {
        const s = try self.createTerminal(@as(u64, b));
        const last = self.root.guard.prev;
        insertAfter(last, s);
        try self.checkDigram(last);
    }

    pub fn addBytes(self: *Grammar,  []const u8) !void {
        for (data) |b| try self.addByte(b);
    }

    pub fn flattenToBytes(self: *Grammar, allocator: std.mem.Allocator, limit: usize) ![]u8 {
        var out = std.ArrayList(u8).init(allocator);
        defer out.deinit();
        try self.emitRule(self.root, &out, limit);
        return try out.toOwnedSlice();
    }

    fn emitRule(self: *Grammar, r: *Rule, out: *std.ArrayList(u8), limit: usize) !void {
        var it = r.guard.next;
        while (it != r.guard) : (it = it.next) {
            if (out.items.len >= limit) return;
            switch (it.kind) {
                .Terminal => try out.append(@as(u8, @intCast(it.terminal & 0xFF))),
                .NonTerminal => try self.emitRule(it.rule.?, out, limit),
                .Guard => unreachable,
            }
        }
    }
};
