const std = @import("std");

const State = struct {
    len: usize,
    link: i32,
    next: std.AutoHashMap(u8, i32),
};

pub const SuffixAutomaton = struct {
    allocator: std.mem.Allocator,
    states: std.ArrayList(State),
    last: i32,

    pub fn init(allocator: std.mem.Allocator) !SuffixAutomaton {
        var sa = SuffixAutomaton{
            .allocator = allocator,
            .states = std.ArrayList(State).init(allocator),
            .last = 0,
        };
        try sa.states.append(.{
            .len = 0,
            .link = -1,
            .next = std.AutoHashMap(u8, i32).init(allocator),
        });
        return sa;
    }

    pub fn deinit(self: *SuffixAutomaton) void {
        for (self.states.items) |*st| st.next.deinit();
        self.states.deinit();
    }

    pub fn extend(self: *SuffixAutomaton, ch: u8) !void {
        const cur: i32 = @intCast(self.states.items.len);
        const last_u: usize = @intCast(self.last);
        try self.states.append(.{
            .len = self.states.items[last_u].len + 1,
            .link = 0,
            .next = std.AutoHashMap(u8, i32).init(self.allocator),
        });

        var p = self.last;
        while (p != -1) {
            const pu: usize = @intCast(p);
            if (self.states.items[pu].next.contains(ch)) break;
            try self.states.items[pu].next.put(ch, cur);
            p = self.states.items[pu].link;
        }

        if (p == -1) {
            self.states.items[@intCast(cur)].link = 0;
        } else {
            const pu: usize = @intCast(p);
            const q = self.states.items[pu].next.get(ch).?;
            const qu: usize = @intCast(q);
            if (self.states.items[pu].len + 1 == self.states.items[qu].len) {
                self.states.items[@intCast(cur)].link = q;
            } else {
                const clone: i32 = @intCast(self.states.items.len);

                var clone_next = std.AutoHashMap(u8, i32).init(self.allocator);
                var it = self.states.items[qu].next.iterator();
                while (it.next()) |e| try clone_next.put(e.key_ptr.*, e.value_ptr.*);

                try self.states.append(.{
                    .len = self.states.items[pu].len + 1,
                    .link = self.states.items[qu].link,
                    .next = clone_next,
                });

                while (p != -1) {
                    const p2u: usize = @intCast(p);
                    if (self.states.items[p2u].next.get(ch)) |v| {
                        if (v == q) {
                            try self.states.items[p2u].next.put(ch, clone);
                            p = self.states.items[p2u].link;
                            continue;
                        }
                    }
                    break;
                }

                self.states.items[qu].link = clone;
                self.states.items[@intCast(cur)].link = clone;
            }
        }

        self.last = cur;
    }

    pub fn buildFromBytes(self: *SuffixAutomaton,  []const u8) !void {
        for (data) |b| try self.extend(b);
    }
};
