const std = @import("std");

pub const SparseMatrix = struct {
    allocator: std.mem.Allocator,
    values: []f32,
    col_indices: []u32,
    row_ptr: []u32,

    pub fn deinit(self: *SparseMatrix) void {
        self.allocator.free(self.values);
        self.allocator.free(self.col_indices);
        self.allocator.free(self.row_ptr);
        self.* = undefined;
    }

    pub fn rows(self: *const SparseMatrix) usize {
        return if (self.row_ptr.len == 0) 0 else self.row_ptr.len - 1;
    }

    pub fn rowRange(self: *const SparseMatrix, r: u32) struct { start: u32, end: u32 } {
        const start = self.row_ptr[@intCast(r)];
        const end = self.row_ptr[@intCast(r + 1)];
        return .{ .start = start, .end = end };
    }
};

fn u128Key(a: u32, b: u32) u128 {
    return (@as(u128, a) << 64) | @as(u128, b);
}

pub fn calculatePPMI(allocator: std.mem.Allocator, tokens: []const u64, window_size: usize) !SparseMatrix {
    var vocab_map = std.AutoHashMap(u64, u32).init(allocator);
    defer vocab_map.deinit();

    var vocab_list = std.ArrayList(u64).init(allocator);
    defer vocab_list.deinit();

    for (tokens) |t| {
        if (!vocab_map.contains(t)) {
            const id: u32 = @intCast(vocab_list.items.len);
            try vocab_list.append(t);
            try vocab_map.put(t, id);
        }
    }

    const v: usize = vocab_list.items.len;
    if (v == 0) {
        return SparseMatrix{
            .allocator = allocator,
            .values = try allocator.alloc(f32, 0),
            .col_indices = try allocator.alloc(u32, 0),
            .row_ptr = try allocator.alloc(u32, 0),
        };
    }

    var counts = try allocator.alloc(u64, v);
    defer allocator.free(counts);
    @memset(counts, 0);

    var co_counts = std.AutoHashMap(u128, u64).init(allocator);
    defer co_counts.deinit();

    var dense = try allocator.alloc(u32, tokens.len);
    defer allocator.free(dense);

    for (tokens, 0..) |t, i| dense[i] = vocab_map.get(t).?;

    for (dense) |id| counts[@intCast(id)] += 1;

    const n = dense.len;
    if (n == 0) {
        return SparseMatrix{
            .allocator = allocator,
            .values = try allocator.alloc(f32, 0),
            .col_indices = try allocator.alloc(u32, 0),
            .row_ptr = try allocator.alloc(u32, 0),
        };
    }

    var i: usize = 0;
    while (i < n) : (i += 1) {
        const a = dense[i];
        var j: usize = 1;
        while (j <= window_size and i + j < n) : (j += 1) {
            const b = dense[i + j];
            if (a == b) continue;
            const lo: u32 = if (a < b) a else b;
            const hi: u32 = if (a < b) b else a;
            const k = u128Key(lo, hi);
            const cur = co_counts.get(k) orelse 0;
            try co_counts.put(k, cur + 1);
        }
    }

    const total_windows_f: f32 = @floatFromInt(@max(@as(u64, 1), @as(u64, n)));

    var row_lists = try allocator.alloc(std.ArrayList(struct { col: u32, val: f32 }), v);
    defer {
        for (row_lists) |*al| al.deinit();
        allocator.free(row_lists);
    }
    for (row_lists) |*al| al.* = std.ArrayList(struct { col: u32, val: f32 }).init(allocator);

    var it = co_counts.iterator();
    while (it.next()) |e| {
        const key = e.key_ptr.*;
        const co = e.value_ptr.*;

        const lo: u32 = @intCast(key >> 64);
        const hi: u32 = @intCast(key & 0xFFFF_FFFF_FFFF_FFFF);

        const c_lo = counts[@intCast(lo)];
        const c_hi = counts[@intCast(hi)];

        const p_xy: f32 = @as(f32, @floatFromInt(co)) / total_windows_f;
        const p_x: f32 = @as(f32, @floatFromInt(c_lo)) / total_windows_f;
        const p_y: f32 = @as(f32, @floatFromInt(c_hi)) / total_windows_f;

        const denom = p_x * p_y;
        if (denom <= 0 or p_xy <= 0) continue;

        const pmi = std.math.log2(p_xy / denom);
        if (pmi > 0) {
            try row_lists[@intCast(lo)].append(.{ .col = hi, .val = pmi });
            try row_lists[@intCast(hi)].append(.{ .col = lo, .val = pmi });
        }
    }

    var nnz: usize = 0;
    for (row_lists) |*al| nnz += al.items.len;

    var values = try allocator.alloc(f32, nnz);
    var col_indices = try allocator.alloc(u32, nnz);
    var row_ptr = try allocator.alloc(u32, v + 1);

    var offset: usize = 0;
    row_ptr[0] = 0;

    var r: usize = 0;
    while (r < v) : (r += 1) {
        std.sort.insertion(struct { col: u32, val: f32 }, row_lists[r].items, {}, struct {
            fn lessThan(_: void, a: struct { col: u32, val: f32 }, b: struct { col: u32, val: f32 }) bool {
                return a.col < b.col;
            }
        }.lessThan);

        for (row_lists[r].items) |item| {
            values[offset] = item.val;
            col_indices[offset] = item.col;
            offset += 1;
        }
        row_ptr[r + 1] = @intCast(offset);
    }

    return SparseMatrix{
        .allocator = allocator,
        .values = values,
        .col_indices = col_indices,
        .row_ptr = row_ptr,
    };
