const std = @import("std");

pub const PersistenceError = error{
    IoError,
    CorruptLog,
    OutOfMemory,
};

const Header = packed struct {
    op: u8,
    len: u32,
    crc32: u32,
};

fn crc(bytes: []const u8) u32 {
    return std.hash.Crc32.hash(bytes);
}

pub const WAL = struct {
    file: std.fs.File,
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator, path: []const u8) !WAL {
        const file = try std.fs.cwd().createFile(path, .{ .read = true, .truncate = false });
        return .{ .file = file, .allocator = allocator };
    }

    pub fn close(self: *WAL) void {
        self.file.close();
    }

    pub fn log(self: *WAL, op: u8,  []const u8) !void {
        var h = Header{
            .op = op,
            .len = @intCast(data.len),
            .crc32 = crc(data),
        };
        try self.file.writeAll(std.mem.asBytes(&h));
        if (data.len > 0) try self.file.writeAll(data);
        try self.file.sync();
    }

    pub fn replay(self: *WAL, callback: *const fn (op: u8,  []const u8) anyerror!void) !void {
        try self.file.seekTo(0);
        var br = std.io.bufferedReader(self.file.reader());
        var r = br.reader();

        while (true) {
            var h: Header = undefined;
            const n = r.read(std.mem.asBytes(&h)) catch return PersistenceError.IoError;
            if (n == 0) break;
            if (n != @sizeOf(Header)) return PersistenceError.CorruptLog;

            const len: usize = @intCast(h.len);
            var buf = try self.allocator.alloc(u8, len);
            defer self.allocator.free(buf);

            if (len > 0) {
                const got = r.readAll(buf) catch return PersistenceError.IoError;
                if (got != len) return PersistenceError.CorruptLog;
            }

            if (crc(buf) != h.crc32) return PersistenceError.CorruptLog;
            try callback(h.op, buf);
        }
    }
};

pub fn snapshot(path: []const u8,  []const u8) !void {
    var file = try std.fs.cwd().createFile(path, .{ .truncate = true });
    defer file.close();
    try file.writeAll(data);
    try file.sync();
}

pub fn loadSnapshot(allocator: std.mem.Allocator, path: []const u8) ![]u8 {
    var file = try std.fs.cwd().openFile(path, .{}) catch return PersistenceError.IoError;
    defer file.close();
    const stat = try file.stat();
    const size: usize = @intCast(stat.size);
    var buf = try allocator.alloc(u8, size);
    const got = try file.readAll(buf);
    if (got != size) {
        allocator.free(buf);
        return PersistenceError.IoError;
    }
    return buf;
}
