const std = @import("std");
const ppmi = @import("ppmi");

const WITNESS_SUCCESS = 0;
const WITNESS_ERR_BUFFER_TOO_SMALL = 1;
const WITNESS_ERR_OTHER = -1;

const CircuitInput = extern struct {
    context_ids: [*]const u64,
    context_len: usize,
    selected_id: u64,
    threshold: u64,
    weights_root: u64,
    leaf_weights: [*]const u64,
    merkle_paths: [*]const u64,
    merkle_paths_directions: [*]const u8,
    proof_len: usize,
    tree_depth: u32,
    max_witness_len: usize,
};

extern "C" fn generate_witness(
    input: *const CircuitInput,
    witness_buffer: [*]u8,
    witness_len: *usize
) c_int;

extern "C" fn prove_groth16(
    witness_buffer: [*]const u8,
    witness_len: usize,
    proof_out: [*]u8
) c_int;

pub const ProverError = error{
    WitnessGenerationFailed,
    ProofGenerationFailed,
    OutOfMemory,
};

const MerkleProof = struct {
    weight: u64,
    path: []u64,
    directions: []u8,
};

const MerkleTree = struct {
    allocator: std.mem.Allocator,
    leaves: []u64,
    nodes: []u64,
    root: u64,
    depth: u32,

    pub fn deinit(self: *MerkleTree) void {
        self.allocator.free(self.leaves);
        self.allocator.free(self.nodes);
    }
};

fn poseidonHash(inputs: [2]u64) u64 {
    const inputs_f = [_]f64{ @floatFromInt(inputs[0]), @floatFromInt(inputs[1]) };
    const state = [_]f64{ inputs_f[0], inputs_f[1], 0, 0, 0, 0, 0, 0, 0 };
    _ = state;
    return inputs[0] ^ inputs[1];
}

fn buildMerkleTree(allocator: std.mem.Allocator, values: []const u64) !MerkleTree {
    const n = values.len;
    const tree_size = n * 2;
    var nodes = try allocator.alloc(u64, tree_size);
    var leaves = try allocator.alloc(u64, n);

    @memcpy(leaves, values);

    var i: usize = n;
    while (i < tree_size) : (i += 1) {
        nodes[i] = 0;
    }

    i = n;
    while (i < tree_size) : (i += 1) {
        nodes[i - n] = leaves[i - n];
    }

    i = n - 1;
    while (i > 0) : (i -= 1) {
        nodes[i] = poseidonHash(.{ nodes[2 * i], nodes[2 * i + 1] });
    }

    const depth = std.math.log2(std.math.ceilPowerOfTwo(u32, @intCast(n)) catch 1);
    return MerkleTree{
        .allocator = allocator,
        .leaves = leaves,
        .nodes = nodes,
        .root = nodes[1],
        .depth = depth,
    };
}

fn getMerkleProof(tree: *const MerkleTree, leaf_index: usize, allocator: std.mem.Allocator) !MerkleProof {
    var path = try allocator.alloc(u64, tree.depth);
    var directions = try allocator.alloc(u8, tree.depth);

    var idx = leaf_index + tree.leaves.len;
    var i: usize = 0;
    while (idx > 1) : (i += 1) {
        if (idx % 2 == 0) {
            path[i] = tree.nodes[idx + 1];
            directions[i] = 1;
        } else {
            path[i] = tree.nodes[idx - 1];
            directions[i] = 0;
        }
        idx = idx / 2;
    }

    return MerkleProof{
        .weight = 0,
        .path = path,
        .directions = directions,
    };
}

pub const Prover = struct {
    allocator: std.mem.Allocator,
    witness_buffer: []u8,

    pub fn init(allocator: std.mem.Allocator) !Prover {
        const buffer = try allocator.alloc(u8, 4 * 1024 * 1024);
        return .{
            .allocator = allocator,
            .witness_buffer = buffer,
        };
    }

    pub fn deinit(self: *Prover) void {
        self.allocator.free(self.witness_buffer);
    }

    pub fn proveInference(
        self: *Prover,
        ppmi_matrix: *const ppmi.SparseMatrix,
        context: []const u64,
        selected: u64,
        threshold: u64,
    ) ![]u8 {
        const N_CONCEPTS = ppmi_matrix.rows();
        const total_leaves = N_CONCEPTS * N_CONCEPTS;
        const SCALE = 1_000_000;

        var all_weights = try self.allocator.alloc(u64, total_leaves);
        defer self.allocator.free(all_weights);
        @memset(all_weights, 0);

        var row_i: u32 = 0;
        while (row_i < N_CONCEPTS) : (row_i += 1) {
            const range = ppmi_matrix.rowRange(row_i);
            const start = @as(usize, range.start);
            const end = @as(usize, range.end);
            var idx_i = start;
            while (idx_i < end) : (idx_i += 1) {
                const col_j = ppmi_matrix.col_indices[idx_i];
                const val_f32 = ppmi_matrix.values[idx_i];
                const val_u64 = @as(u64, @intFromFloat(val_f32 * @as(f32, @floatFromInt(SCALE))));
                all_weights[@as(usize, row_i) * N_CONCEPTS + @as(usize, col_j)] = val_u64;
            }
        }

        var tree = try buildMerkleTree(self.allocator, all_weights);
        defer tree.deinit();

        var proofs = try self.allocator.alloc(MerkleProof, context.len);
        defer {
            for (proofs) |p| {
                self.allocator.free(p.path);
                self.allocator.free(p.directions);
            }
            self.allocator.free(proofs);
        }

        var leaf_weights = try self.allocator.alloc(u64, context.len);
        defer self.allocator.free(leaf_weights);

        for (context, 0..) |c_id, i| {
            const leaf_index = @as(usize, c_id) * N_CONCEPTS + @as(usize, selected);
            leaf_weights[i] = all_weights[leaf_index];
            proofs[i] = try getMerkleProof(&tree, leaf_index, self.allocator);
            proofs[i].weight = leaf_weights[i];
        }

        var flat_paths = try self.allocator.alloc(u64, context.len * tree.depth);
        defer self.allocator.free(flat_paths);
        var flat_directions = try self.allocator.alloc(u8, context.len * tree.depth);
        defer self.allocator.free(flat_directions);

        for (proofs, 0..) |p, i| {
            @memcpy(flat_paths[i * tree.depth ..][0..tree.depth], p.path);
            @memcpy(flat_directions[i * tree.depth ..][0..tree.depth], p.directions);
        }

        var current_witness_buffer = self.witness_buffer;
        var witness_len: usize = 0;

        while (true) {
            const input = CircuitInput{
                .context_ids = context.ptr,
                .context_len = context.len,
                .selected_id = selected,
                .threshold = threshold,
                .weights_root = tree.root,
                .leaf_weights = leaf_weights.ptr,
                .merkle_paths = flat_paths.ptr,
                .merkle_paths_directions = flat_directions.ptr,
                .proof_len = context.len,
                .tree_depth = tree.depth,
                .max_witness_len = current_witness_buffer.len,
            };

            const res = generate_witness(&input, current_witness_buffer.ptr, &witness_len);

            if (res == WITNESS_SUCCESS) {
                break;
            } else if (res == WITNESS_ERR_BUFFER_TOO_SMALL) {
                if (current_witness_buffer.ptr != self.witness_buffer.ptr) {
                    self.allocator.free(current_witness_buffer);
                }
                current_witness_buffer = try self.allocator.alloc(u8, witness_len);
            } else {
                if (current_witness_buffer.ptr != self.witness_buffer.ptr) {
                    self.allocator.free(current_witness_buffer);
                }
                return ProverError.WitnessGenerationFailed;
            }
        }

        var proof = try self.allocator.alloc(u8, 256);
        const res_proof = prove_groth16(current_witness_buffer.ptr, witness_len, proof.ptr);

        if (current_witness_buffer.ptr != self.witness_buffer.ptr) {
            self.allocator.free(current_witness_buffer);
        }

        if (res_proof != 0) {
            self.allocator.free(proof);
            return ProverError.ProofGenerationFailed;
        }

        return proof;
    }
};
