const std = @import("std");
const seq = @import("sequitur");
const pp = @import("ppmi");

pub const Generator = struct {
    allocator: std.mem.Allocator,
    grammar: *seq.Grammar,
    matrix: ?*pp.SparseMatrix,
    rng: std.rand.DefaultPrng,
    vocab_size: u32,

    pub fn init(allocator: std.mem.Allocator, grammar: *seq.Grammar, matrix: ?*pp.SparseMatrix, seed: u64, vocab_size: u32) Generator {
        return .{
            .allocator = allocator,
            .grammar = grammar,
            .matrix = matrix,
            .rng = std.rand.DefaultPrng.init(seed),
            .vocab_size = if (vocab_size == 0) 256 else vocab_size,
        };
    }

    fn pickUniformByte(self: *Generator) u8 {
        const r = self.rng.random();
        return r.intRangeAtMost(u8, 32, 126);
    }

    fn pickFromPPMI(self: *Generator, last: u32) u8 {
        const m = self.matrix orelse return self.pickUniformByte();
        if (last >= m.rows()) return self.pickUniformByte();
        const rr = m.rowRange(last);
        const start: usize = @intCast(rr.start);
        const end: usize = @intCast(rr.end);
        if (end <= start) return self.pickUniformByte();

        var sum: f64 = 0;
        var i: usize = start;
        while (i < end) : (i += 1) sum += @as(f64, m.values[i]);

        if (!(sum > 0)) return self.pickUniformByte();

        const r = self.rng.random().float(f64) * sum;
        var acc: f64 = 0;
        i = start;
        while (i < end) : (i += 1) {
            acc += @as(f64, m.values[i]);
            if (acc >= r) {
                const col = m.col_indices[i];
                return @as(u8, @intCast(col & 0xFF));
            }
        }
        return @as(u8, @intCast(m.col_indices[end - 1] & 0xFF));
    }

    pub fn generate(self: *Generator, seed_bytes: []const u8, length: usize) ![]u8 {
        var out = std.ArrayList(u8).init(self.allocator);
        defer out.deinit();

        if (seed_bytes.len > 0) try out.appendSlice(seed_bytes);

        var last_id: u32 = if (seed_bytes.len == 0) 0 else @intCast(seed_bytes[seed_bytes.len - 1]);

        while (out.items.len < length) {
            const b = self.pickFromPPMI(last_id);
            try out.append(b);
            last_id = @intCast(b);
        }

        return try out.toOwnedSlice();
    }

    pub fn generateFromGrammar(self: *Generator, limit: usize) ![]u8 {
        return try self.grammar.flattenToBytes(self.allocator, limit);
    }
};
